	/**
	 * Default Constructor
	 */
    public DiagnosisService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new DiagnosisEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(DiagnosisRepository.class) );
		this.validator		= applicationContext.getBean(DiagnosisValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Diagnosis
	 */
		public Diagnosis createDiagnosis( CreateDiagnosisCommand command ) {

		Diagnosis entity = new Diagnosis();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setDiagnosisId( command.getDiagnosisId() );
            entity.setCode( command.getCode() );
            entity.setDescription( command.getDescription() );
            entity.setOnsetDate( command.getOnsetDate() );
            entity.setCertainty( command.getCertainty() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Diagnosis {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateDiagnosisCommand
	 * @return		Diagnosis
	 */
	public Diagnosis updateDiagnosis( UpdateDiagnosisCommand command ) {

		Diagnosis entity = new Diagnosis();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setDiagnosisId( command.getDiagnosisId() );
            entity.setCode( command.getCode() );
            entity.setDescription( command.getDescription() );
            entity.setOnsetDate( command.getOnsetDate() );
            entity.setEncounter( command.getEncounter() );
            entity.setPatient( command.getPatient() );
            entity.setCertainty( command.getCertainty() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Diagnosis {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteDiagnosisCommand
	 */
	public void delete( DeleteDiagnosisCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getDiagnosisId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Diagnosis {0} ", id );

	}

	/**
	 * Method to retrieve the Diagnosis via DiagnosisFetchOneSummary
	 * @param 	summary DiagnosisFetchOneSummary
	 * @return 	DiagnosisFetchOneResponse
	 */
	public Diagnosis getDiagnosis( DiagnosisFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "DiagnosisFetchOneSummary arg cannot be null" );

		Diagnosis entity = null;
		UUID id = summary.getDiagnosisId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Diagnosis using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Diagnosiss
	 *
	 * @return 	List<Diagnosis>
	 */
    public List<Diagnosis> getAllDiagnosis() {
		List<Diagnosis> list = projector.findAll( new FindAllDiagnosisQuery() );
		return list;
	}

	/**
	 * assign Encounter on Diagnosis
	 * @param		command AssignEncounterToDiagnosisCommand
	 */
	public void assignEncounter( AssignEncounterToDiagnosisCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignEncounter(command.getDiagnosisId(), command.getAssignment());

	}

	/**
	 * unAssign Encounter on Diagnosis
	 * @param		command UnAssignEncounterFromDiagnosisCommand
	 */
	public void unAssignEncounter( UnAssignEncounterFromDiagnosisCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignEncounter(command.getDiagnosisId());
	}
	
	/**
	 * assign Patient on Diagnosis
	 * @param		command AssignPatientToDiagnosisCommand
	 */
	public void assignPatient( AssignPatientToDiagnosisCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignPatient(command.getDiagnosisId(), command.getAssignment());

	}

	/**
	 * unAssign Patient on Diagnosis
	 * @param		command UnAssignPatientFromDiagnosisCommand
	 */
	public void unAssignPatient( UnAssignPatientFromDiagnosisCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignPatient(command.getDiagnosisId());
	}
	




